-- The QUICK-I-GROOVE code key (Code keys -> Parting -> QUICK-I-GROOVE), from
-- the ISCAR e-catalog's QUICK-I-GROOVE families (GQIN inserts, GQHINR/L bars);
-- kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.quickigroove', $ck${"title": "QUICK-I-GROOVE code key – inserts and bars", "subtitle": "Precision ground inserts with 4 cutting edges (GQIN) for internal grooving and recessing, and GQHINR/L bars", "example": "GQIN 1.50-0.10", "decoder": "quick-i-groove", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "GQIN", "rows": [{"code": "GQIN", "meaning": "4 cutting edges precision ground insert for internal grooving and recessing"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "1.50", "rows": [{"code": "#.##", "meaning": "Cutting width in mm (1.00 – 3.00)"}]}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "0.10", "rows": [{"code": "#.##", "meaning": "Corner radius in mm (e.g. 0.10)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "GQHIN", "meaning": "Internal grooving and turning bars carrying GQIN inserts (GQHINR / GQHINL)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (16, 20)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "C", "meaning": "With coolant supply"}]}, {"key": "t-dmin", "title": "Tool – minimum bore diameter", "rows": [{"code": "##.#", "meaning": "Minimum bore diameter Dmin in mm (e.g. 16.5, 24)"}]}, {"key": "t-length", "title": "Tool – reduced length", "rows": [{"code": "##", "meaning": "Reduced (neck) length LDRED in mm (e.g. 20, 40)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
